class Empleado:
    def __init__(self, nombre, sueldo):
        self.nombre = nombre
        self.sueldo = sueldo

    def descripcion(self):
        return f"{self.nombre} gana {self.sueldo}"


class Gerente(Empleado):
    def __init__(self, nombre, sueldo, equipo):
        super().__init__(nombre, sueldo)
        self.equipo = equipo

    def descripcion(self):
        return super().descripcion() + f" (gerente de {self.equipo} personas)"

